const dias = { segunda: 'MONDAY', terca: 'TUESDAY', quarta: 'WEDNESDAY', quinta: 'THURSDAY', sexta: 'FRIDAY', sabado: 'SATURDAY', domingo: 'SUNDAY' };
const horario = $('Webhook Horário').item.json.body.horario_funcionamento || {};
const shifts = [];
for (const [diaPt, diaEn] of Object.entries(dias)) {
  const d = horario[diaPt];
  if (!d || !d.aberto) continue;
  const [abreH, abreM] = (d.abre || '00:00').split(':').map(Number);
  const [fechaH, fechaM] = (d.fecha || '00:00').split(':').map(Number);
  const duracao = (fechaH * 60 + fechaM) - (abreH * 60 + abreM);
  if (duracao <= 0) continue;
  shifts.push({ dayOfWeek: diaEn, start: `${d.abre}:00`, duration: duracao });
}
return [{ json: { ...$json, shifts } }];

