const ctx = $('Checar token 99Food em cache (pausar)').item.json;
const resp = $json;
const tokenData = resp.data || {};
const ok = resp.errno === 0 && !!tokenData.auth_token;
const store = $getWorkflowStaticData('global');
store.food99Tokens = store.food99Tokens || {};
if (ok) {
  store.food99Tokens[ctx.app_shop_id_valor] = {
    authToken: tokenData.auth_token,
    expiresAt: tokenData.token_expiration_time ? tokenData.token_expiration_time * 1000 : Date.now() + 21600000,
  };
}
return [{ json: { ...ctx, auth_token: ok ? tokenData.auth_token : null, token_valido: ok, token_erro: ok ? null : (resp.errmsg || 'erro desconhecido ao obter token') } }];

const w = $('Webhook Criar').item.json.body;
const inicio = new Date(w.inicio);
const fim = new Date(w.fim);
const minutos = Math.max(1, Math.round((fim - inicio) / 60000));
// 99Food so aceita 4 durações fixas (10/20/30min/até o fim do dia) -- sem
// equivalente pra uma janela livre como a do iFood, arredonda pra mais perto.
let pauseTime;
if (minutos <= 15) pauseTime = 1;
else if (minutos <= 25) pauseTime = 2;
else if (minutos <= 45) pauseTime = 3;
else pauseTime = 4;
return [{ json: { ...$json, pause_time: pauseTime, pause_reason_code: 1006 } }];

