const dias = { segunda: 1, terca: 2, quarta: 3, quinta: 4, sexta: 5, sabado: 6, domingo: 7 };
const horario = $('Webhook Horário').item.json.body.horario_funcionamento || {};
// 99Food agrupa dias com o MESMO horario num unico bloco (bizDay:[...]), ao
// inves de um shift por dia como o iFood -- agrupa por chave "abre-fecha".
const grupos = {};
for (const [diaPt, diaNum] of Object.entries(dias)) {
  const d = horario[diaPt];
  if (!d || !d.aberto) continue;
  const abre = d.abre || '00:00';
  const fecha = d.fecha || '00:00';
  const chave = abre + '-' + fecha;
  grupos[chave] = grupos[chave] || { bizDay: [], abre, fecha };
  grupos[chave].bizDay.push(diaNum);
}
const biz_day_time = Object.values(grupos).map(g => ({
  bizDay: g.bizDay.sort((a, b) => a - b),
  bizTime: [{ begin: g.abre, end: g.fecha }],
}));
return [{ json: { ...$json, biz_day_time } }];
